Copy the workbook, read the cached values in Sheet1!A2:A150 (falling back to Sheet2 if needed), and compute distinct values in first-appearance order. Write those values into Sheet1!B2:B150, leaving the remaining cells empty. Apply the requested Calibri font, yellow fill/borders, hide Sheet2, and set Sheet1 active.

```python
import shutil
import openpyxl
from openpyxl.styles import Font, PatternFill, Border, Side

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

def clean_value(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

def collect_values(sheet_name):
    try:
        s = vals[sheet_name]
    except KeyError:
        return []
    out = []
    for r in range(2, 151):
        v = clean_value(s.cell(row=r, column=1).value)
        if v is not None:
            out.append(v)
    return out

source = collect_values("Sheet1")
if not source:
    source = collect_values("Sheet2")

seen = set()
unique = []
for v in source:
    if isinstance(v, str):
        key = ("s", v.lower())
    else:
        key = ("v", v)
    if key not in seen:
        seen.add(key)
        unique.append(v)

if "Sheet1" in wb.sheetnames:
    ws = wb["Sheet1"]
else:
    ws = wb.create_sheet("Sheet1")

for r in range(2, 151):
    idx = r - 2
    cell = ws.cell(row=r, column=2)
    if idx < len(unique):
        cell.value = unique[idx]
    else:
        cell.value = None

font = Font(name="Calibri")
fill = PatternFill(start_color="FFFF00", end_color="FFFF00", fill_type="solid")
thin = Side(style="thin", color="000000")
border = Border(left=thin, right=thin, top=thin, bottom=thin)
no_border = Border()

for row in ws.iter_rows(min_row=1, max_row=151, min_col=1, max_col=2):
    for cell in row:
        cell.font = font

for r in range(2, 151):
    c = ws.cell(row=r, column=2)
    c.fill = fill
    c.border = border

for r in range(1, 14):
    ws.cell(row=r, column=1).border = border
for r in range(14, 152):
    ws.cell(row=r, column=1).border = no_border

ws.sheet_view.showGridLines = False

if "Sheet2" in wb.sheetnames:
    wb["Sheet2"].sheet_state = "hidden"

wb.active = wb.sheetnames.index("Sheet1")
wb.save(OUT)

print("unique_count", len(unique))
print("first_values", unique[:10])
